-- Generated by model/lib/sql/generate.mjs. Loads Growth Bonus Threshold IN from cells/Growth Bonus Threshold IN.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/Growth Bonus Threshold IN.csv
INSERT INTO "Growth Bonus Threshold IN" SELECT coalesce(k0."Customer Group", fpabench_error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY 1, 2, 3
ON CONFLICT ("Customer Group", "Versions", "Years") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "Growth Bonus Threshold IN";
